using System.Net;
using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
namespace RaceDay.MvC.Services;
/// <summary>Forwards requests to the Part 2 API and keeps its session cookie inside the current browser session.</summary>
public class RaceDayApiClient(IHttpClientFactory factory, IHttpContextAccessor accessor) {
 private readonly JsonSerializerOptions json = new(JsonSerializerDefaults.Web){PropertyNameCaseInsensitive=true};
 private HttpClient Client => factory.CreateClient("RaceDayApi");
 private ISession Session => accessor.HttpContext!.Session;
 private HttpRequestMessage Request(HttpMethod method,string path,object? body=null){var req=new HttpRequestMessage(method,path); if(Session.TryGetValue("RaceDayApiCookie",out var bytes)){var cookie=Encoding.UTF8.GetString(bytes);if(!string.IsNullOrWhiteSpace(cookie))req.Headers.TryAddWithoutValidation("Cookie",cookie);} if(body!=null)req.Content=JsonContent.Create(body,options:json);return req;}
 private async Task<HttpResponseMessage> Send(HttpRequestMessage req){var response=await Client.SendAsync(req);if(response.Headers.TryGetValues("Set-Cookie",out var values)){var cookie=values.Select(x=>x.Split(';')[0]).FirstOrDefault(x=>x.StartsWith(".RaceDay.Session=",StringComparison.OrdinalIgnoreCase)||x.StartsWith(".AspNetCore.Session=",StringComparison.OrdinalIgnoreCase));if(cookie!=null)Session.Set("RaceDayApiCookie",Encoding.UTF8.GetBytes(cookie));}return response;}
 public async Task<(bool Ok,string? Error,T? Data)> Get<T>(string path){try{using var req=Request(HttpMethod.Get,path);using var res=await Send(req);var raw=await res.Content.ReadAsStringAsync();if(!res.IsSuccessStatusCode)return(false,ErrorText(raw,res.StatusCode),default);return(true,null,JsonSerializer.Deserialize<T>(raw,json));}catch(Exception ex){return(false,$"Could not contact the RaceDay API. Check that the Part 2 API is running and ApiSettings:BaseUrl is correct. Details: {ex.Message}",default);}}
 public async Task<(bool Ok,string? Error,T? Data)> Send<T>(HttpMethod method,string path,object? body=null){try{using var req=Request(method,path,body);using var res=await Send(req);var raw=await res.Content.ReadAsStringAsync();if(!res.IsSuccessStatusCode)return(false,ErrorText(raw,res.StatusCode),default);if(string.IsNullOrWhiteSpace(raw))return(true,null,default);try{return(true,null,JsonSerializer.Deserialize<T>(raw,json));}catch{return(true,null,default);}}catch(Exception ex){return(false,$"Could not contact the RaceDay API. Check that the API is running. Details: {ex.Message}",default);}}
 public async Task<(bool Ok,string? Error)> SendNoData(HttpMethod method,string path,object? body=null){var r=await Send<JsonElement>(method,path,body);return(r.Ok,r.Error);}
 public async Task<(bool Ok,string? Error,T? Data)> SendFile<T>(string path, IFormFile file){try{using var req=Request(HttpMethod.Post,path);using var content=new MultipartFormDataContent();await using var stream=file.OpenReadStream();var fileContent=new StreamContent(stream);fileContent.Headers.ContentType=new MediaTypeHeaderValue(file.ContentType);content.Add(fileContent,"file",file.FileName);req.Content=content;using var res=await Send(req);var raw=await res.Content.ReadAsStringAsync();if(!res.IsSuccessStatusCode)return(false,ErrorText(raw,res.StatusCode),default);return(string.IsNullOrWhiteSpace(raw),null,string.IsNullOrWhiteSpace(raw)?default:JsonSerializer.Deserialize<T>(raw,json));}catch(Exception ex){return(false,$"Could not upload the image. Details: {ex.Message}",default);}}
 public async Task<(bool Ok,string? Error,byte[]? Data,string? ContentType)> GetFile(string path){try{using var req=Request(HttpMethod.Get,path);using var res=await Send(req);if(!res.IsSuccessStatusCode)return(false,ErrorText(await res.Content.ReadAsStringAsync(),res.StatusCode),null,null);return(true,null,await res.Content.ReadAsByteArrayAsync(),res.Content.Headers.ContentType?.MediaType);}catch(Exception ex){return(false,ex.Message,null,null);}}
 private static string ErrorText(string raw,HttpStatusCode code){try{using var doc=JsonDocument.Parse(raw);if(doc.RootElement.TryGetProperty("message",out var m))return m.GetString()??$"Request failed ({(int)code}).";if(doc.RootElement.TryGetProperty("title",out var t))return t.GetString()??$"Request failed ({(int)code}).";}catch{}return string.IsNullOrWhiteSpace(raw)?$"Request failed ({(int)code}).":raw;}
}